/** Yes counts fully, Partial counts as half credit, No/unanswered count
 *  as zero - an insurer does not give credit for a control that is only
 *  half in place, but this app should still show partial progress rather
 *  than flattening it to the same as "not started". */
function creditFor(status               )         {
  switch (status) {
    case 'yes':
      return 1;
    case 'partial':
      return 0.5;
    case 'no':
    case 'unanswered':
      return 0;
    default:
      // Cardinal rule: an unknown/malformed status is never given credit.
      // Storage already filters these out, but if one ever reaches scoring
      // (a future import, a schema drift) it counts as not-in-place, never a
      // pass, and can never turn the whole score into NaN.
      return 0;
  }
}

                       
                   
                        
               
  

                                 
                            
                
                       
                        
                       
                       
                   
  

                               
                       
                        
                       
                       
                   
                          
                                                                    
                                                                   
                                                                  
                  
                                  
  

function answerMap(answers          )                      {
  const map = new Map                ();
  for (const answer of answers) {
    map.set(answer.controlId, answer);
  }
  return map;
}

function statusFor(map                     , controlId        )                {
  return map.get(controlId)?.status ?? 'unanswered';
}

function roundPercent(earned        , possible        )         {
  if (possible === 0) return 0;
  return Math.round((earned / possible) * 100);
}

/** Within equal weight, order gaps worst-first isn't right either - a
 *  "no" and an "unanswered" are equally far from done, and a "partial"
 *  is the closest win, so partial sorts after no/unanswered at the same
 *  weight (closing it takes less work, but the bigger gaps get named
 *  first). */
const STATUS_GAP_RANK                                = {
  unanswered: 0,
  no: 0,
  partial: 1,
  yes: 2,
};

export function computeReadiness(controls           , answers          )                  {
  const map = answerMap(answers);

  let earned = 0;
  let possible = 0;
  let inPlaceCount = 0;
  let partialCount = 0;
  let gapCount = 0;
  let unansweredCount = 0;
  const gaps            = [];
  const categoryTotals = new Map 
                    
                                                                                                      
   ();

  for (const control of controls) {
    const status = statusFor(map, control.id);
    const credit = creditFor(status);
    earned += credit * control.weight;
    possible += control.weight;

    if (!categoryTotals.has(control.category)) {
      categoryTotals.set(control.category, { earned: 0, possible: 0, total: 0, inPlace: 0, partial: 0, gap: 0 });
    }
    const catTotal = categoryTotals.get(control.category) ;
    catTotal.earned += credit * control.weight;
    catTotal.possible += control.weight;
    catTotal.total += 1;

    if (status === 'yes') {
      inPlaceCount += 1;
      catTotal.inPlace += 1;
    } else {
      if (status === 'partial') {
        partialCount += 1;
        catTotal.partial += 1;
      } else {
        gapCount += 1;
        catTotal.gap += 1;
        if (status === 'unanswered') unansweredCount += 1;
      }
      gaps.push({ control, status, note: map.get(control.id)?.note ?? '' });
    }
  }

  gaps.sort((a, b) => {
    if (b.control.weight !== a.control.weight) return b.control.weight - a.control.weight;
    const rankDiff = STATUS_GAP_RANK[a.status] - STATUS_GAP_RANK[b.status];
    if (rankDiff !== 0) return rankDiff;
    return a.control.title.localeCompare(b.control.title);
  });

  const categories                      = Array.from(categoryTotals.entries())
    .map(([category, t]) => ({
      category,
      label: CONTROL_CATEGORY_LABELS[category],
      scorePercent: roundPercent(t.earned, t.possible),
      totalControls: t.total,
      inPlaceCount: t.inPlace,
      partialCount: t.partial,
      gapCount: t.gap,
    }))
    .sort((a, b) => a.label.localeCompare(b.label));

  return {
    scorePercent: roundPercent(earned, possible),
    totalControls: controls.length,
    inPlaceCount,
    partialCount,
    gapCount,
    unansweredCount,
    gaps,
    categories,
  };
}
